pub type AppError = Failed(String)

fn make(s: String) -> Result<Int64, AppError> {
    return Ok(1)
}

fn apply(p: fn(String) -> Result<Int64, AppError>) -> Result<Int64, AppError> {
    return p("x")
}

pub fn main() -> Result<(), AppError> {
    let v = apply(|s: String| make(s)?)?
    return Ok(())
}

